'use strict';

const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let pos = 0;

const L = Number(tokens[pos++]);
const C = Number(tokens[pos++]);
const equations = [];
const present = new Array(676).fill(false);

function variableId(name) {
  return (name.charCodeAt(0) - 97) * 26 + name.charCodeAt(1) - 97;
}

function addEquation(names, target) {
  const counts = new Map();
  for (const name of names) {
    const id = variableId(name);
    present[id] = true;
    counts.set(id, (counts.get(id) || 0) + 1);
  }
  equations.push({
    counts,
    remaining: BigInt(target),
    unknown: counts.size
  });
}

for (let r = 0; r < L; r++) {
  const names = [];
  for (let c = 0; c < C; c++) names.push(tokens[pos++]);
  addEquation(names, tokens[pos++]);
}

for (let c = 0; c < C; c++) {
  const names = [];
  for (let r = 0; r < L; r++) {
    // Grid names are read row by row, so column equations are built below.
  }
  names.length = 0;
  // The grid is stored separately to construct column equations.
  // This placeholder is replaced by the stored grid values.
}

// Re-read the grid names from the input tokens to construct column equations.
const grid = Array.from({ length: L }, () => new Array(C));
pos = 2;
for (let r = 0; r < L; r++) {
  for (let c = 0; c < C; c++) grid[r][c] = tokens[pos++];
  pos++; // Skip row sum.
}
for (let c = 0; c < C; c++) {
  const names = [];
  for (let r = 0; r < L; r++) names.push(grid[r][c]);
  addEquation(names, tokens[pos++]);
}

const adjacency = Array.from({ length: 676 }, () => []);
for (let e = 0; e < equations.length; e++) {
  for (const [id, coefficient] of equations[e].counts) {
    adjacency[id].push([e, coefficient]);
  }
}

const values = new Array(676);
const known = new Array(676).fill(false);
const queue = [];

for (let e = 0; e < equations.length; e++) {
  if (equations[e].unknown === 1) queue.push(e);
}

let head = 0;
while (head < queue.length) {
  const e = queue[head++];
  const equation = equations[e];
  if (equation.unknown !== 1) continue;

  let id, coefficient;
  for (const entry of equation.counts) {
    if (!known[entry[0]]) {
      id = entry[0];
      coefficient = entry[1];
      break;
    }
  }
  if (id === undefined) continue;

  const value = equation.remaining / BigInt(coefficient);
  known[id] = true;
  values[id] = value;

  for (const [otherEquation, count] of adjacency[id]) {
    const current = equations[otherEquation];
    current.remaining -= BigInt(count) * value;
    current.unknown--;
    if (current.unknown === 1) queue.push(otherEquation);
  }
}

const output = [];
for (let id = 0; id < 676; id++) {
  if (present[id]) {
    const name = String.fromCharCode(97 + Math.floor(id / 26), 97 + (id % 26));
    output.push(`${name} ${values[id].toString()}`);
  }
}

console.log(output.join('\n'));
